from typing import List

class Solution:
    def maximumCoins(self, coins: List[List[int]], k: int) -> int:
        coins.sort()

        def scan(intervals: List[List[int]]) -> int:
            ans = 0
            cur = 0
            left = 0

            for right, (l, r, c) in enumerate(intervals):
                cur += (r - l + 1) * c

                window_start = r - k + 1

                while left <= right and intervals[left][1] < window_start:
                    cur -= (intervals[left][1] - intervals[left][0] + 1) * intervals[left][2]
                    left += 1

                extra = 0
                if left <= right and intervals[left][0] < window_start:
                    extra = (window_start - intervals[left][0]) * intervals[left][2]

                ans = max(ans, cur - extra)

            return ans

        ans = scan(coins)

        mirrored = [[-r, -l, c] for l, r, c in coins]
        mirrored.sort()

        return max(ans, scan(mirrored))
